CREATE TABLE acceptance_suite_versions (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, suite_id TEXT NOT NULL, version_label TEXT NOT NULL, kind TEXT NOT NULL, routing_taxonomy_id TEXT NOT NULL, routing_taxonomy_version TEXT NOT NULL, frozen INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, frozen_at DATETIME);
CREATE TABLE acceptance_cases (id TEXT PRIMARY KEY, suite_version_id TEXT NOT NULL, payload TEXT NOT NULL, FOREIGN KEY (suite_version_id) REFERENCES acceptance_suite_versions(id));
CREATE TABLE acceptance_runs (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, suite_version_id TEXT NOT NULL, profile TEXT NOT NULL, snapshot TEXT NOT NULL, metrics TEXT, gate TEXT NOT NULL DEFAULT 'pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (suite_version_id) REFERENCES acceptance_suite_versions(id));
CREATE TABLE acceptance_case_results (id TEXT PRIMARY KEY, run_id TEXT NOT NULL, case_id TEXT NOT NULL, payload TEXT NOT NULL, FOREIGN KEY (run_id) REFERENCES acceptance_runs(id));
